import json
with open('benchmark/source_data.json') as f:
  mb=json.load(f)['model_benchmarks']
dims=mb['dimensions']
for r in mb['data']:
  if r['model']=='GPT-4o-mini':
    print([r[k] for k in dims])
for r in mb['data']:
  if r['model']=='Claude 3 Haiku':
    print('Haiku', [r[k] for k in dims])
