/* Publication-ready, data-dense styling for xychart */

/* Base text */
svg { background: #ffffff; }
text { fill: #111827 !important; font-family: Inter, Arial, Helvetica, sans-serif !important; }

/* Axes */
.axis path,
.axis line {
  stroke: #6B7280 !important;
  stroke-width: 1.2px !important;
  shape-rendering: crispEdges;
}

/* Grid */
.grid line {
  stroke: #E5E7EB !important;
  stroke-width: 1px !important;
}

/* Series line defaults */
.path {
  fill: none;
  stroke-width: 2.2px;
  opacity: 0.65;
}

/* Family colors (approx Okabe-Ito + accessible) */
/* GPT = blue */
.path.series0 { stroke: #2563EB !important; }
.path.series1 { stroke: #60A5FA !important; }

/* Claude = purple */
.path.series2 { stroke: #7C3AED !important; }
.path.series3 { stroke: #A78BFA !important; }

/* Gemini = green */
.path.series4 { stroke: #16A34A !important; }
.path.series5 { stroke: #4ADE80 !important; }

/* LLaMA = orange */
.path.series6 { stroke: #EA580C !important; }
.path.series7 { stroke: #FDBA74 !important; }

/* Qwen = red */
.path.series8 { stroke: #DC2626 !important; }
.path.series9 { stroke: #F87171 !important; }

/* Emphasize top performers (first 3 series) */
.path.series0,
.path.series2,
.path.series4 {
  stroke-width: 3.6px !important;
  opacity: 0.9 !important;
}

/* De-emphasize others slightly */
.path.series1,
.path.series3,
.path.series5,
.path.series6,
.path.series7,
.path.series8,
.path.series9 {
  opacity: 0.6 !important;
}

/* Legend styling */
.legend text { font-size: 12px !important; }
CSS

